-- PostgreSQL 버전 (H2 MODE=PostgreSQL 호환)
-- 운동 사전 (FR-WORK-01, SDD 6.5·8.1). 모든 사용자가 같이 쓰는 참조 데이터라 user_id가 없다.
-- 부상 제외는 exercise_catalog_load_areas(그 운동이 부담을 주는 부위)로 판정한다 (D18 ②, 초안).

CREATE TABLE exercise_catalog (
    id                BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    code              VARCHAR(50)   NOT NULL,
    name_ko           VARCHAR(100)  NOT NULL,
    phase             VARCHAR(20)   NOT NULL,
    focus_area        VARCHAR(20)   NOT NULL,
    equipment         VARCHAR(20)   NOT NULL,
    intensity         INT           NOT NULL,
    unit              VARCHAR(20)   NOT NULL,
    default_sets      INT           NOT NULL,
    default_reps      INT           NULL,
    default_seconds   INT           NULL,
    seconds_per_rep   NUMERIC(4,1)  NOT NULL,
    rest_seconds      INT           NOT NULL,
    pose_exercise_key VARCHAR(50)   NULL,
    active            BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at        TIMESTAMP(6)  NOT NULL,
    updated_at        TIMESTAMP(6)  NOT NULL,

    PRIMARY KEY (id),
    CONSTRAINT uk_exercise_catalog_code UNIQUE (code),
    CONSTRAINT ck_exercise_catalog_intensity CHECK (intensity BETWEEN 1 AND 3),
    CONSTRAINT ck_exercise_catalog_amount CHECK (
        (unit = 'REPS' AND default_reps IS NOT NULL) OR (unit = 'SECONDS' AND default_seconds IS NOT NULL))
);

CREATE TABLE exercise_catalog_load_areas (
    exercise_id BIGINT      NOT NULL,
    body_area   VARCHAR(20) NOT NULL,

    PRIMARY KEY (exercise_id, body_area),
    CONSTRAINT fk_exercise_load_area_exercise
        FOREIGN KEY (exercise_id) REFERENCES exercise_catalog (id) ON DELETE CASCADE
);

